function M.buildPlan(group)
  local order = assert(M.orders[group], "Group must be 1-4")
  local result = {}
  for index, pair in ipairs(order) do
    local set = M.sets[pair[2]]
    local block = {name=pair[1],contentSet=pair[2],orientation=pair[1]:sub(1,1),
      tabLoad=pair[1]:sub(3,3)=="L" and "low" or "high", topic=set.topic,trials={},
      expectedTabCount=pair[1]:sub(3,3)=="L" and 6 or 16,
      taskOrder=pair[1]:sub(3,3)=="L" and set.lowOrder or set.highOrder}
    for i, original in ipairs(set.trials) do
      local trial = {}
      for k,v in pairs(original) do trial[k]=v end
      block.trials[i]=trial
    end
    result[index]=block
  end
  return result
end
return M